        code: "\"use client\"\n\nimport {\n    Button,\n    Input,\n    Label,\n    Sheet,\n    SheetClose,\n    SheetContent,\n    SheetDescription,\n    SheetFooter,\n    SheetHeader,\n    SheetTitle,\n    SheetTrigger,\n} from \"@saasflare/ui\"\n\n/** A right-side panel for editing settings, with a form body and footer. */\nexport function Demo() {\n    return (\n        <Sheet>\n            <SheetTrigger asChild>\n                <Button variant=\"outline\">Edit profile</Button>\n            </SheetTrigger>\n            <SheetContent side=\"right\">\n                <SheetHeader>\n                    <SheetTitle>Edit profile</SheetTitle>\n                    <SheetDescription>\n                        Update your account details. Changes are saved instantly.\n                    </SheetDescription>\n                </SheetHeader>\n                <div className=\"flex flex-col gap-4 px-4\">\n                    <div className=\"flex flex-col gap-2\">\n                        <Label htmlFor=\"sheet-name\">Display name</Label>\n                        <Input id=\"sheet-name\" defaultValue=\"Lina Hartmann\" />\n                    </div>\n                    <div className=\"flex flex-col gap-2\">\n                        <Label htmlFor=\"sheet-email\">Email</Label>\n                        <Input id=\"sheet-email\" type=\"email\" defaultValue=\"lina@acme.io\" />\n                    </div>\n                </div>\n                <SheetFooter>\n                    <Button>Save changes</Button>\n                    <SheetClose asChild>\n                        <Button variant=\"ghost\">Cancel</Button>\n                    </SheetClose>\n                </SheetFooter>\n            </SheetContent>\n        </Sheet>\n    )\n}",
